INSERT INTO "public"."site_settings" ("id", "key", "value", "type", "created_at", "updated_at") VALUES ('07d1f66c-07fb-4129-bc0a-6f24b0847bc0', 'welcome_title', 'Welcome to Ga South Municipal Assembly', 'text', '2026-01-16 19:52:55.665661+00', '2026-01-25 10:09:28.131+00'), ('406265b8-0cdc-4419-bbe5-9ad07faf4320', 'mission', 'The Ga South Municipal Assembly exist to provide an effective and efficient service delivery to ensure quality and dignified life for all citizens and business through balanced and excellent delivery of socio-economic policies within the context of good local governance', 'text', '2026-01-16 19:52:55.665661+00', '2026-01-25 10:13:19.794+00'), ('5a0cb4f8-acc8-4dd1-a40a-bc8470455134', 'core_values', 'The Assembly has adapted the following core values as part of it mandate to ensure successful implementation of the Medium Term Development Plan (2018-2021);  Excellence Smartness Proactiveness Respect Team Work', 'text', '2026-01-16 19:52:55.665661+00', '2026-01-25 10:14:26.847+00'), ('b594e657-83fc-45fe-a1e3-e60d1dd1b4c2', 'welcome_content', 'The Ga South Municipal Assembly was established by Legislative Instrument (L.I) 2134 in 2012. It was carved out of the then Ga West District Assembly with Ngleshie Amanfro as its capital. The Assembly is responsible for the overall development of the municipality and operates under the Ministry of Local Government, Decentralization and Rural Development.', 'textarea', '2026-01-16 19:52:55.665661+00', '2026-01-19 14:50:50.017+00'), ('c5ffb53c-3f24-4c2a-b8d3-a8cfa16324e1', 'vision', 'A well-managed city of excellence for service delivery for citizens and business prosperity.', 'text', '2026-01-16 19:52:55.665661+00', '2026-01-25 10:12:52.051+00');